trigger AppliedDiscount on Applied_Discount__c (after insert, after update) {
    Set<Id> orderIds = new Set<Id>();
    for (Applied_Discount__c ad : Trigger.new) {
        if (ad.Order__c != null) {
            orderIds.add(ad.Order__c);
        }
    }
    if (orderIds.isEmpty()) return;

    // Get all Applied_Discount__c for affected Orders
    Map<Id, List<Applied_Discount__c>> orderToDiscounts = new Map<Id, List<Applied_Discount__c>>();
    for (Applied_Discount__c ad : [SELECT Id, Order__c, Amount_Discounted__c FROM Applied_Discount__c WHERE Order__c IN :orderIds]) {
        if (!orderToDiscounts.containsKey(ad.Order__c)) {
            orderToDiscounts.put(ad.Order__c, new List<Applied_Discount__c>());
        }
        orderToDiscounts.get(ad.Order__c).add(ad);
    }

    // Get Orders
    List<Order> ordersToUpdate = new List<Order>();
    for (Order o : [SELECT Id, TotalAmount, Order_Amount_After_Discount__c FROM Order WHERE Id IN :orderIds]) {
        List<Applied_Discount__c> discounts = orderToDiscounts.get(o.Id);
        if (discounts == null || discounts.isEmpty()) continue;
        Decimal maxDiscount = 0;
        for (Applied_Discount__c ad : discounts) {
            if (ad.Amount_Discounted__c != null && ad.Amount_Discounted__c > maxDiscount) {
                maxDiscount = ad.Amount_Discounted__c;
            }
        }
        o.Order_Amount_After_Discount__c = o.TotalAmount != null ? o.TotalAmount - maxDiscount : null;
        ordersToUpdate.add(o);
    }
    if (!ordersToUpdate.isEmpty()) {
        update ordersToUpdate;
    }
}
